            Node("memo-nodes-eq", "memoNodes_eq", "Every memoized node equals its complete original node",
                "For every natural fuel and every original finite index, memoNodes equals the unchanged original nodes decoder. The equation covers hits, misses, mismatches and all fuel values.", DescribeRole.Theorem),
            Node("nodes-fun-eq", "nodes_fun_eq", "Equality of the whole fuel-indexed decoder functions",
                "Two applications of function extensionality turn pointwise node equality into equality of the complete original and memoized decoder functions. All original constructor fields, including child functions, are preserved.", DescribeRole.Theorem),
            Node("check-eq-original", "check_eq_original", "The complete actual-context checker is unchanged",
